import java.util.Scanner;

public class OneBasedArithmetic {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long n = in.nextLong();
        long[] ones = new long[17];
        for (int i = 1; i < 17; i++) {
            ones[i] = 10 * ones[i - 1] + 1;
        }
        long result = recursiveCompute(ones, n, 16);
        System.out.println(result);
        in.close();
    }

    private static long recursiveCompute(long[] ones, long n, int index) {
        long quotient = n / ones[index];
        long remainder = n % ones[index];
        long totalUsed = quotient * index;
        if (remainder == 0) {
            return totalUsed;
        } else {
            long optionA = recursiveCompute(ones, remainder, index - 1);
            long optionB = index + recursiveCompute(ones, ones[index] - remainder, index - 1);
            return totalUsed + Math.min(optionA, optionB);
        }
    }
}
